+  .membership {
+    grid-template-columns: 1fr;
+  }
+
+  .section__heading .eyebrow,
+  .section__heading h2,
+  .section__heading p:not(.eyebrow) {
+    grid-column: auto;
+    grid-row: auto;
+  }
+
+  .hero {
+    min-height: auto;
+    padding-top: 4rem;
+  }
+
+  .product-grid,
+  .editorial-grid {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .editorial-card--feature {
+    grid-column: 1 / -1;
+  }
+}
+
+@media (max-width: 640px) {
+  main,
+  .site-header,
+  .site-footer {
+    width: min(100% - 1rem, 1180px);
+  }
+
+  .hero__showcase {
+    min-height: 500px;
+  }
+
+  .showcase-card--large {
+    inset: 0;
+  }
+
+  .showcase-card--floating {
+    right: 0.8rem;
+    bottom: 1.4rem;
+  }
+
+  .product-grid,
+  .editorial-grid,
+  .editorial-card--feature,
+  .signup-form,
+  .site-footer {
+    grid-template-columns: 1fr;
+  }
+
+  .site-footer {
+    align-items: flex-start;
+  }
+}
+



